package com.visualticks;

import com.google.inject.Inject;
import com.visualticks.config.TickSettings;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;

/**
 * Lays out and draws one tick set. Subclasses supply only which counter and which
 * settings factory they use.
 *
 * <p>Subclass names are persisted: RuneLite's {@code Overlay.getName()} returns the simple
 * class name, and the overlay manager saves each overlay's dragged screen position under
 * keys prefixed with it. Renaming {@code VisualTicksOverlayOne/Two/Three} silently resets
 * every user's layout. {@code OverlayWiringTest} pins the names.
 */
public abstract class BaseVisualTicksOverlay extends Overlay
{
    protected VisualTicksPlugin plugin;
    protected VisualTicksConfig config;
    protected Client client;
    protected volatile boolean configChanged = true;
    protected TickSettings settings;
    protected final List<TickPosition> positions = new ArrayList<>();
    protected final Dimension dimension = new Dimension();

    @Inject
    public BaseVisualTicksOverlay(VisualTicksPlugin plugin, VisualTicksConfig config, Client client)
    {
        this.plugin = plugin;
        this.config = config;
        this.client = client;
        setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
    }

    public void onConfigChanged() {
        configChanged = true;
    }

    protected abstract TickSettings readSettings();
    /** This set's 0-based counter; the label drawn for tick {@code i} is {@code i + 1}. */
    protected abstract int getCurrentTick();

    protected void calculateSizes(Graphics2D g) {
        positions.clear();

        // Nothing to draw, so claim no space: the maths below seeds maxCol/maxRow at 0 and
        // would report a phantom one-cell box for OverlayManager to reserve and snap to.
        if (settings.numberOfTicks <= 0) {
            dimension.setSize(0, 0);
            return;
        }

        Font originalFont = g.getFont();
        g.setFont(originalFont.deriveFont((float) settings.textSize));
        FontMetrics fm = g.getFontMetrics();

        int textHeight = fm.getAscent();

        // First pass: one cell shared by every tick, so all columns and rows sit on a
        // single pitch. Labels differ in width ("10" is wider than "9"), so sizing each
        // cell on its own label would break the grid. See issue #5.
        //
        // Width and height are tracked apart because only width varies with the label:
        // folding the widest label into the height too would push the rows away from
        // each other for a purely horizontal reason.
        int cellWidth = settings.showShape ? settings.shapeSize : 0;
        int cellHeight = cellWidth;
        if (settings.showText) {
            cellHeight = Math.max(cellHeight, textHeight);
            for (int i = 0; i < settings.numberOfTicks; i++) {
                cellWidth = Math.max(cellWidth, fm.stringWidth(String.valueOf(i + 1)));
            }
        }

        // Negative spacing legitimately tightens the layout, but below -cell it inverts the
        // pitch: each tick would sit left of / above the last, marching out of the reported
        // bounds and driving the Dimension negative. Clamp at total overlap. See issue #6.
        int horizontalSpacing = Math.max(settings.horizontalSpacing, -cellWidth);
        int verticalSpacing = Math.max(settings.verticalSpacing, -cellHeight);

        // A stored config value can sit outside its @Range — ConfigManager returns it
        // unvalidated — so amountPerRow may be 0 and divide by zero below. See issue #7.
        int amountPerRow = Math.max(1, settings.amountPerRow);

        // The cell is sized for the widest label, so a corner-anchored shape would sit
        // adrift from the number it carries. Centre it in the cell the label centres in.
        int shapeInsetX = settings.showShape ? (cellWidth - settings.shapeSize) / 2 : 0;
        int shapeInsetY = settings.showShape ? (cellHeight - settings.shapeSize) / 2 : 0;

        int maxCol = 0;
        int maxRow = 0;

        for (int i = 0; i < settings.numberOfTicks; i++)
        {
            int row = i / amountPerRow;
            int col = i % amountPerRow;
            int x = col * (cellWidth + horizontalSpacing);
            int y = row * (cellHeight + verticalSpacing);

            TickPosition position = new TickPosition(x + shapeInsetX, y + shapeInsetY);

            if (settings.showText) {
                int textWidth = fm.stringWidth(String.valueOf(i + 1));
                position.fontX = x + (cellWidth - textWidth) / 2;
                position.fontY = y + (cellHeight + textHeight) / 2;
            }
            positions.add(position);

            maxRow = Math.max(maxRow, row);
            maxCol = Math.max(maxCol, col);
        }

        // n cells have n - 1 gaps between them: drop the spacing after the last column and
        // row so the reported box ends where the drawing does.
        dimension.width = (maxCol + 1) * (cellWidth + horizontalSpacing) - horizontalSpacing;
        dimension.height = (maxRow + 1) * (cellHeight + verticalSpacing) - verticalSpacing;

        g.setFont(originalFont);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if(configChanged) {
            configChanged = false;
            try {
                settings = readSettings();
                calculateSizes(graphics);
            } catch (RuntimeException ex) {
                // Retry next frame rather than latching a transient failure forever.
                configChanged = true;
                throw ex;
            }
        }

        if(!settings.exclusiveTab.matchesAnyTab() && client.getVarcIntValue(VarClientID.TOPLEVEL_PANEL) != settings.exclusiveTab.getIndex()) return null;

        Font originalFont = graphics.getFont();
        graphics.setFont(graphics.getFont().deriveFont((float) settings.textSize));

        for (int i = 0; i < settings.numberOfTicks; i++)
        {
            TickPosition position = positions.get(i);
            if (settings.showShape) {
                graphics.setColor(i == getCurrentTick() ? settings.currentTickColour : settings.tickColour);
                switch(settings.shape) {
                    case SQUARE:
                        graphics.fillRect(position.shapeX, position.shapeY, settings.shapeSize, settings.shapeSize);
                        break;
                    case CIRCLE:
                        graphics.fillOval(position.shapeX, position.shapeY, settings.shapeSize, settings.shapeSize);
                        break;
                    case ROUNDED_SQUARE:
                        graphics.fillRoundRect(position.shapeX, position.shapeY, settings.shapeSize, settings.shapeSize, settings.arc, settings.arc);
                        break;
                }
            }
            if (settings.showText) {
                graphics.setColor(i == getCurrentTick() ? settings.currentTextColour : settings.textColour);
                graphics.drawString(String.valueOf(i + 1), position.fontX, position.fontY);
            }
        }

        graphics.setFont(originalFont);
        return dimension;
    }
}

package com.visualticks;

public class TickPosition {
    public int shapeX;
    public int shapeY;
    public int fontX;
    public int fontY;

    public TickPosition(int shapeX, int shapeY) {
        this.shapeX = shapeX;
        this.shapeY = shapeY;
    }
}

package com.visualticks;
import com.visualticks.config.HotkeyMode;
import com.visualticks.config.InterfaceLayer;
import com.visualticks.config.InterfaceTab;
import com.visualticks.config.TickShape;
import net.runelite.client.config.*;
import java.awt.*;
import java.awt.event.KeyEvent;

/**
 * Every setting of the plugin, in config group {@value #GROUP_NAME}.
 *
 * <p><b>Key names are stored user data.</b> RuneLite saves each value under its
 * {@code @ConfigItem} {@code keyName}, so renaming one silently resets that setting for
 * every user. Treat section keys the same way.
 *
 * <p><b>Enum constant names are stored user data too.</b> RuneLite stores a chosen enum
 * value by its constant name and reads it back with {@code valueOf}, so renaming a constant
 * resets that setting for every user who picked it. This covers every enum in
 * {@code com.visualticks.config} that a setting returns.
 *
 * <p>Each {@code keyName} equals its method name, which the plugin relies on when it
 * builds keys like {@code "numberOfTicks" + suffix}; {@code ConfigConventionsTest}
 * enforces that.
 *
 * <p>Layout: one hotkey section, then three tick-set blocks (One, Two, Three). The three
 * blocks declare the same settings, suffixed {@code One}/{@code Two}/{@code Three}, and
 * differ only in descriptions, section and the default of {@code isEnabledN} (on for One,
 * off for Two and Three). A setting added to one block must be added to all three, and to
 * the matching {@code TickSettings} factory; {@code ConfigConventionsTest} and
 * {@code TickSettingsTest} fail otherwise.
 */
@ConfigGroup(VisualTicksConfig.GROUP_NAME)
public interface VisualTicksConfig extends Config {
    String GROUP_NAME = "visualticks";

    /**
     * Lower bound of every {@code numberOfTicksN}. {@code @Range} only bounds the panel
     * slider, so the adjust hotkeys enforce the same bound themselves from this constant.
     */
    int MIN_TICKS = 2;

    /** Upper bound of every {@code numberOfTicksN}, enforced the same way as {@link #MIN_TICKS}. */
    int MAX_TICKS = 30;

    //region Hotkey Settings
    @ConfigSection(
            name = "Hotkey settings",
            description = "Settings for hotkeys",
            position = 0
    )
    String hotkeySettings = "hotkeySettings";

    @ConfigItem(
            position = 0,
            keyName = "tickResetHotkey",
            name = "Tick Reset Hotkey",
            description = "Hotkey to reset tick counter",
            section = hotkeySettings
    )
    default Keybind tickResetHotkey() {
        return new Keybind(KeyEvent.VK_BACK_QUOTE, KeyEvent.VK_UNDEFINED);
    }

    // Both the global pair below and every per-set pair stay visible whichever mode is
    // picked: @ConfigItem has only a static hidden flag, with no way to hide or disable an
    // item based on another setting. The mode decides which pair keyPressed honours.
    @ConfigItem(
            position = 1,
            keyName = "tickAdjustHotkeyMode",
            name = "Tick Adjust Hotkeys",
            description = "Global: the two hotkeys below adjust every tick set at once. "
                    + "Independent: each tick set is adjusted by its own hotkeys, set in that section.",
            section = hotkeySettings
    )
    default HotkeyMode tickAdjustHotkeyMode() {
        return HotkeyMode.GLOBAL;
    }

    @ConfigItem(
            position = 2,
            keyName = "tickIncreaseHotkey",
            name = "Tick Increase Hotkey",
            description = "Hotkey to add a tick to every set. Only used when Tick Adjust Hotkeys is Global.",
            section = hotkeySettings
    )
    default Keybind tickIncreaseHotkey() {
        return Keybind.NOT_SET;
    }

    @ConfigItem(
            position = 3,
            keyName = "tickDecreaseHotkey",
            name = "Tick Decrease Hotkey",
            description = "Hotkey to remove a tick from every set, hiding a set already at " + MIN_TICKS + ". "
                    + "Only used when Tick Adjust Hotkeys is Global.",
            section = hotkeySettings
    )
    default Keybind tickDecreaseHotkey() {
        return Keybind.NOT_SET;
    }
    //endregion

    //region Tick settings - One
    @ConfigSection(
            name = "Tick settings - One",
            description = "Settings for the first set of ticks",
            position = 1
    )
    // No "One" suffix: set One predates multi-set support and kept its original key.
    // Whether RuneLite persists section state (such as collapsed) under this key is
    // unverified, so treat the key as persisted and leave it unsuffixed.
    String tickSettings = "tickSettings";

    @ConfigItem(
            keyName = "isEnabledOne",
            name = "Enabled",
            description = "Enable the first set of ticks",
            section = tickSettings,
            position = 0
    )
    default boolean isEnabledOne() {
        return true;
    }

    @ConfigItem(
            keyName = "shouldShowTickShapeOne",
            name = "Show Tick Shape",
            description = "Show the shape of the first set of ticks",
            section = tickSettings,
            position = 1
    )
    default boolean shouldShowTickShapeOne() {
        return true;
    }

    @ConfigItem(
            keyName = "tickShapeOne",
            name = "Tick shape",
            description = "The shape of the ticks",
            section = tickSettings,
            position = 2
    )
    default TickShape tickShapeOne() {
        return TickShape.CIRCLE;
    }

    @ConfigItem(
            keyName = "exclusiveTabOne",
            name = "Only show if on tab",
            description = "Show the ticks only when the selected tab is active",
            section = tickSettings,
            position = 3
    )
    default InterfaceTab exclusiveTabOne() {
        return InterfaceTab.ALL;
    }

    @ConfigItem(
            keyName = "interfaceLayerOne",
            name = "Interface layer",
            description = "Draw the ticks above or behind interfaces such as the bank. Behind also draws"
                    + " under hitsplats, HP bars and overhead text, and in Fixed mode clips the ticks to"
                    + " the game view, so a set over the chatbox or side panel disappears",
            section = tickSettings,
            position = 4
    )
    default InterfaceLayer interfaceLayerOne() {
        return InterfaceLayer.ABOVE;
    }

    @ConfigItem(
            keyName = "numberOfTicksOne",
            name = "Number of ticks",
            description = "Number of ticks to display",
            section = tickSettings,
            position = 5
    )
    @Range(min = MIN_TICKS, max = MAX_TICKS)
    default int numberOfTicksOne() {
        return 2;
    }

    @ConfigItem(
            keyName = "amountPerRowOne",
            name = "Amount per row",
            description = "How many ticks to display per row",
            section = tickSettings,
            position = 6
    )
    @Range(min = 1)
    default int amountPerRowOne() {
        return 8;
    }

    @ConfigItem(
            keyName = "tickColourOne",
            name = "Tick colour",
            description = "The colour of the ticks",
            section = tickSettings,
            position = 7
    )
    @Alpha
    default Color tickColourOne() {
        return new Color(41, 128, 185);
    }

    @ConfigItem(
            keyName = "currentTickColourOne",
            name = "Current tick colour",
            description = "The colour of the current tick",
            section = tickSettings,
            position = 8
    )
    @Alpha
    default Color currentTickColourOne() {
        return new Color(236, 240, 241);
    }

    @ConfigItem(
            keyName = "sizeOfTickShapesOne",
            name = "Size of ticks",
            description = "How many pixels to make the tick shapes",
            section = tickSettings,
            position = 9
    )
    @Range(min = 1)
    default int sizeOfTickShapesOne() {
        return 32;
    }

    @ConfigItem(
            keyName = "tickArcOne",
            name = "Tick arc(rounded square)",
            description = "The arc of the corners of the rounded square tick shape",
            section = tickSettings,
            position = 10
    )
    @Range(max = 100)
    default int tickArcOne() {
        return 10;
    }

    @ConfigItem(
            keyName = "shouldShowTextOne",
            name = "Show text",
            description = "Show each tick's number on it",
            section = tickSettings,
            position = 11
    )
    default boolean shouldShowTextOne() {
        return true;
    }

    @ConfigItem(
            keyName = "tickTextSizeOne",
            name = "Tick text size",
            description = "The size of the text on the ticks",
            section = tickSettings,
            position = 12
    )
    @Range(min = 1, max = 100)
    default int tickTextSizeOne() {
        return 15;
    }

    @ConfigItem(
            keyName = "tickTextColourOne",
            name = "Tick text colour",
            description = "The colour of the text on non-current ticks",
            section = tickSettings,
            position = 13
    )
    @Alpha
    default Color tickTextColourOne() {
        return new Color(236, 240, 241);
    }

    @ConfigItem(
            keyName = "currentTickTextColourOne",
            name = "Current tick text colour",
            description = "The colour of the text on the current tick",
            section = tickSettings,
            position = 14
    )
    @Alpha
    default Color currentTickTextColourOne() {
        return new Color(41, 128, 185);
    }

    @ConfigItem(
            keyName = "horizontalSpacingOne",
            name = "Horizontal spacing",
            description = "The amount of space between ticks on the x-axis",
            section = tickSettings,
            position = 15
    )
    @Range(min = -50)
    default int horizontalSpacingOne() {
        return 5;
    }

    @ConfigItem(
            keyName = "verticalSpacingOne",
            name = "Vertical spacing",
            description = "The amount of space between ticks on the y-axis",
            section = tickSettings,
            position = 16
    )
    @Range(min = -50)
    default int verticalSpacingOne() {
        return 5;
    }

    @ConfigItem(
            keyName = "increaseHotkeyOne",
            name = "Increase Hotkey",
            description = "Hotkey to add a tick to this set. Only used when Tick Adjust Hotkeys is Independent.",
            section = tickSettings,
            position = 17
    )
    default Keybind increaseHotkeyOne() {
        return Keybind.NOT_SET;
    }

    @ConfigItem(
            keyName = "decreaseHotkeyOne",
            name = "Decrease Hotkey",
            description = "Hotkey to remove a tick from this set, hiding it when already at " + MIN_TICKS + ". "
                    + "Only used when Tick Adjust Hotkeys is Independent.",
            section = tickSettings,
            position = 18
    )
    default Keybind decreaseHotkeyOne() {
        return Keybind.NOT_SET;
    }
    //endregion

    //region Tick settings - Two
    @ConfigSection(
            name = "Tick settings - Two",
            description = "Settings for the second set of ticks",
            position = 2
    )
    String tickSettingsTwo = "tickSettingsTwo";

    @ConfigItem(
            keyName = "isEnabledTwo",
            name = "Enabled",
            description = "Enable the second set of ticks",
            section = tickSettingsTwo,
            position = 0
    )
    default boolean isEnabledTwo() {
        return false;
    }

    @ConfigItem(
            keyName = "shouldShowTickShapeTwo",
            name = "Show Tick Shape",
            description = "Show the shape of the second set of ticks",
            section = tickSettingsTwo,
            position = 1
    )
    default boolean shouldShowTickShapeTwo() {
        return true;
    }

    @ConfigItem(
            keyName = "tickShapeTwo",
            name = "Tick shape",
            description = "The shape of the ticks",
            section = tickSettingsTwo,
            position = 2
    )
    default TickShape tickShapeTwo() {
        return TickShape.CIRCLE;
    }

    @ConfigItem(
            keyName = "exclusiveTabTwo",
            name = "Only show if on tab",
            description = "Show the ticks only when the selected tab is active",
            section = tickSettingsTwo,
            position = 3
    )
    default InterfaceTab exclusiveTabTwo() {
        return InterfaceTab.ALL;
    }

    @ConfigItem(
            keyName = "interfaceLayerTwo",
            name = "Interface layer",
            description = "Draw the ticks above or behind interfaces such as the bank. Behind also draws"
                    + " under hitsplats, HP bars and overhead text, and in Fixed mode clips the ticks to"
                    + " the game view, so a set over the chatbox or side panel disappears",
            section = tickSettingsTwo,
            position = 4
    )
    default InterfaceLayer interfaceLayerTwo() {
        return InterfaceLayer.ABOVE;
    }

    @ConfigItem(
            keyName = "numberOfTicksTwo",
            name = "Number of ticks",
            description = "Number of ticks to display",
            section = tickSettingsTwo,
            position = 5
    )
    @Range(min = MIN_TICKS, max = MAX_TICKS)
    default int numberOfTicksTwo() {
        return 2;
    }

    @ConfigItem(
            keyName = "amountPerRowTwo",
            name = "Amount per row",
            description = "How many ticks to display per row",
            section = tickSettingsTwo,
            position = 6
    )
    @Range(min = 1)
    default int amountPerRowTwo() {
        return 8;
    }

    @ConfigItem(
            keyName = "tickColourTwo",
            name = "Tick colour",
            description = "The colour of the ticks",
            section = tickSettingsTwo,
            position = 7
    )
    @Alpha
    default Color tickColourTwo() {
        return new Color(41, 128, 185);
    }

    @ConfigItem(
            keyName = "currentTickColourTwo",
            name = "Current tick colour",
            description = "The colour of the current tick",
            section = tickSettingsTwo,
            position = 8
    )
    @Alpha
    default Color currentTickColourTwo() {
        return new Color(236, 240, 241);
    }

    @ConfigItem(
            keyName = "sizeOfTickShapesTwo",
            name = "Size of ticks",
            description = "How many pixels to make the tick shapes",
            section = tickSettingsTwo,
            position = 9
    )
    @Range(min = 1)
    default int sizeOfTickShapesTwo() {
        return 32;
    }

    @ConfigItem(
            keyName = "tickArcTwo",
            name = "Tick arc(rounded square)",
            description = "The arc of the corners of the rounded square tick shape",
            section = tickSettingsTwo,
            position = 10
    )
    @Range(max = 100)
    default int tickArcTwo() {
        return 10;
    }

    @ConfigItem(
            keyName = "shouldShowTextTwo",
            name = "Show text",
            description = "Show each tick's number on it",
            section = tickSettingsTwo,
            position = 11
    )
    default boolean shouldShowTextTwo() {
        return true;
    }

    @ConfigItem(
            keyName = "tickTextSizeTwo",
            name = "Tick text size",
            description = "The size of the text on the ticks",
            section = tickSettingsTwo,
            position = 12
    )
    @Range(min = 1, max = 100)
    default int tickTextSizeTwo() {
        return 15;
    }

    @ConfigItem(
            keyName = "tickTextColourTwo",
            name = "Tick text colour",
            description = "The colour of the text on non-current ticks",
            section = tickSettingsTwo,
            position = 13
    )
    @Alpha
    default Color tickTextColourTwo() {
        return new Color(236, 240, 241);
    }

    @ConfigItem(
            keyName = "currentTickTextColourTwo",
            name = "Current tick text colour",
            description = "The colour of the text on the current tick",
            section = tickSettingsTwo,
            position = 14
    )
    @Alpha
    default Color currentTickTextColourTwo() {
        return new Color(41, 128, 185);
    }

    @ConfigItem(
            keyName = "horizontalSpacingTwo",
            name = "Horizontal spacing",
            description = "The amount of space between ticks on the x-axis",
            section = tickSettingsTwo,
            position = 15
    )
    @Range(min = -50)
    default int horizontalSpacingTwo() {
        return 5;
    }

    @ConfigItem(
            keyName = "verticalSpacingTwo",
            name = "Vertical spacing",
            description = "The amount of space between ticks on the y-axis",
            section = tickSettingsTwo,
            position = 16
    )
    @Range(min = -50)
    default int verticalSpacingTwo() {
        return 5;
    }

    @ConfigItem(
            keyName = "increaseHotkeyTwo",
            name = "Increase Hotkey",
            description = "Hotkey to add a tick to this set. Only used when Tick Adjust Hotkeys is Independent.",
            section = tickSettingsTwo,
            position = 17
    )
    default Keybind increaseHotkeyTwo() {
        return Keybind.NOT_SET;
    }

    @ConfigItem(
            keyName = "decreaseHotkeyTwo",
            name = "Decrease Hotkey",
            description = "Hotkey to remove a tick from this set, hiding it when already at " + MIN_TICKS + ". "
                    + "Only used when Tick Adjust Hotkeys is Independent.",
            section = tickSettingsTwo,
            position = 18
    )
    default Keybind decreaseHotkeyTwo() {
        return Keybind.NOT_SET;
    }
    //endregion

    //region Tick settings - Three
    @ConfigSection(
            name = "Tick settings - Three",
            description = "Settings for the third set of ticks",
            position = 3
    )
    String tickSettingsThree = "tickSettingsThree";

    @ConfigItem(
            keyName = "isEnabledThree",
            name = "Enabled",
            description = "Enable the third set of ticks",
            section = tickSettingsThree,
            position = 0
    )
    default boolean isEnabledThree() {
        return false;
    }

    @ConfigItem(
            keyName = "shouldShowTickShapeThree",
            name = "Show Tick Shape",
            description = "Show the shape of the third set of ticks",
            section = tickSettingsThree,
            position = 1
    )
    default boolean shouldShowTickShapeThree() {
        return true;
    }

    @ConfigItem(
            keyName = "tickShapeThree",
            name = "Tick shape",
            description = "The shape of the ticks",
            section = tickSettingsThree,
            position = 2
    )
    default TickShape tickShapeThree() {
        return TickShape.CIRCLE;
    }

    @ConfigItem(
            keyName = "exclusiveTabThree",
            name = "Only show if on tab",
            description = "Show the ticks only when the selected tab is active",
            section = tickSettingsThree,
            position = 3
    )
    default InterfaceTab exclusiveTabThree() {
        return InterfaceTab.ALL;
    }

    @ConfigItem(
            keyName = "interfaceLayerThree",
            name = "Interface layer",
            description = "Draw the ticks above or behind interfaces such as the bank. Behind also draws"
                    + " under hitsplats, HP bars and overhead text, and in Fixed mode clips the ticks to"
                    + " the game view, so a set over the chatbox or side panel disappears",
            section = tickSettingsThree,
            position = 4
