	@Test
	public void theGlobalHotkeysAreIgnoredInIndependentMode()
	{
		when(config.tickAdjustHotkeyMode()).thenReturn(HotkeyMode.INDEPENDENT);

		press(globalIncrease);

		verifyNoInteractions(configManager);
