		when(globalIncrease.matches(any(KeyEvent.class))).thenReturn(true);
		KeyEvent event = keyEvent();

		plugin.keyPressed(event);

		assertTrue(event.isConsumed());
	}

	@Test
	public void anUnmatchedKeyIsLeftAlone()
	{
		KeyEvent event = keyEvent();

		plugin.keyPressed(event);

		assertFalse(event.isConsumed());
	}

	/** A set sized by the user and switched off by hand keeps its size when it returns. */
	@Test
	public void revivingASetKeepsTheCountItWasConfiguredWith()
	{
		when(config.tickAdjustHotkeyMode()).thenReturn(HotkeyMode.INDEPENDENT);
		when(config.isEnabledOne()).thenReturn(false);
		when(config.numberOfTicksOne()).thenReturn(8);

		press(increaseOne);

		verify(configManager).setConfiguration(VisualTicksConfig.GROUP_NAME, "isEnabledOne", true);
		verify(configManager, never()).setConfiguration(VisualTicksConfig.GROUP_NAME, "numberOfTicksOne", 2);
	}

	/** A stored count below the minimum is still normalised on the way back in. */
	@Test
	public void revivingASetNormalisesACountBelowTheMinimum()
	{
		when(config.tickAdjustHotkeyMode()).thenReturn(HotkeyMode.INDEPENDENT);
		when(config.isEnabledOne()).thenReturn(false);
		when(config.numberOfTicksOne()).thenReturn(0);

		press(increaseOne);

		// Count first, so the set never reappears at its stale size.
		InOrder inOrder = inOrder(configManager);
		inOrder.verify(configManager).setConfiguration(VisualTicksConfig.GROUP_NAME, "numberOfTicksOne", 2);
		inOrder.verify(configManager).setConfiguration(VisualTicksConfig.GROUP_NAME, "isEnabledOne", true);
	}

	/** Profiles carry their own enabled flags, so a claim must not cross between them. */
	@Test
	public void switchingProfileDropsTheHotkeyClaim()
	{
		press(globalDecrease);
		when(config.isEnabledOne()).thenReturn(false);

		eventBus.post(new ProfileChanged());
		press(globalIncrease);

		verify(configManager, never()).setConfiguration(VisualTicksConfig.GROUP_NAME, "isEnabledOne", true);
	}

	@Test
	public void restartingDropsTheHotkeyClaim() throws Exception
	{
		press(globalDecrease);
		when(config.isEnabledOne()).thenReturn(false);

		plugin.startUp();
		press(globalIncrease);

		verify(configManager, never()).setConfiguration(VisualTicksConfig.GROUP_NAME, "isEnabledOne", true);
	}

	@Test
	public void shutDownRemovesEveryOverlayAndTheKeyListener() throws Exception
	{
		plugin.shutDown();

		verify(overlayManager).remove(overlayOne);
		verify(overlayManager).remove(overlayTwo);
		verify(overlayManager).remove(overlayThree);
		verify(keyManager).unregisterKeyListener(plugin);
	}

	@Test
	public void migrationSplitsLegacyPaddingIntoBothAxes() throws Exception
	{
		when(configManager.getConfiguration(VisualTicksConfig.GROUP_NAME, "paddingBetweenTicksOne")).thenReturn("9");

		plugin.startUp();

		verify(configManager).setConfiguration(VisualTicksConfig.GROUP_NAME, "horizontalSpacingOne", "9");
		verify(configManager).setConfiguration(VisualTicksConfig.GROUP_NAME, "verticalSpacingOne", "9");
		verify(configManager).unsetConfiguration(VisualTicksConfig.GROUP_NAME, "paddingBetweenTicksOne");
	}

	@Test
	public void migrationCoversAllThreeLegacyKeys() throws Exception
	{
		when(configManager.getConfiguration(VisualTicksConfig.GROUP_NAME, "tickPaddingTwo")).thenReturn("3");
		when(configManager.getConfiguration(VisualTicksConfig.GROUP_NAME, "tickPaddingThree")).thenReturn("4");

		plugin.startUp();

		verify(configManager).setConfiguration(VisualTicksConfig.GROUP_NAME, "horizontalSpacingTwo", "3");
		verify(configManager).setConfiguration(VisualTicksConfig.GROUP_NAME, "verticalSpacingTwo", "3");
		verify(configManager).setConfiguration(VisualTicksConfig.GROUP_NAME, "horizontalSpacingThree", "4");
		verify(configManager).setConfiguration(VisualTicksConfig.GROUP_NAME, "verticalSpacingThree", "4");
	}

	@Test
	public void migrationWithoutLegacyValuesWritesNothing() throws Exception
	{
		plugin.startUp();

		verify(configManager, never()).setConfiguration(any(String.class), any(String.class), any(String.class));
		verify(configManager).unsetConfiguration(VisualTicksConfig.GROUP_NAME, "paddingBetweenTicksOne");
		verify(configManager).unsetConfiguration(VisualTicksConfig.GROUP_NAME, "tickPaddingTwo");
		verify(configManager).unsetConfiguration(VisualTicksConfig.GROUP_NAME, "tickPaddingThree");
	}

	@Test
	public void profileChangeRerunsMigration()
	{
		reset(configManager);
		when(configManager.getConfiguration(VisualTicksConfig.GROUP_NAME, "paddingBetweenTicksOne")).thenReturn("7");

		eventBus.post(new ProfileChanged());

		verify(configManager).setConfiguration(VisualTicksConfig.GROUP_NAME, "horizontalSpacingOne", "7");
	}

	private void press(Keybind hotkey)
	{
		when(hotkey.matches(any(KeyEvent.class))).thenReturn(true);
		plugin.keyPressed(keyEvent());
		when(hotkey.matches(any(KeyEvent.class))).thenReturn(false);
	}

	private static KeyEvent keyEvent()
	{
		return new KeyEvent(new Canvas(), KeyEvent.KEY_PRESSED, System.currentTimeMillis(), 0, KeyEvent.VK_R, 'r');
	}
}

package com.visualticks;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Not a test: the dev-client launcher, named and placed per the RuneLite plugin template so
 * {@code ./gradlew runTestClient} can start it. It side-loads the plugin and opens the real
 * game client. {@code loadBuiltin} refuses to run without assertions enabled, which is why
 * the {@code runTestClient} task passes {@code -ea}.
 */
public class VisualTicksPluginTest
{
	// loadBuiltin is generic varargs and not @SafeVarargs; this single-element call is type-correct.
	@SuppressWarnings("unchecked")
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(VisualTicksPlugin.class);
		RuneLite.main(args);
	}
}

package com.visualticks.config;

import com.visualticks.VisualTicksConfig;
import org.junit.Test;

import java.awt.Color;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The three factories are hand-copied, so the failure mode is a getter from the
 * wrong tick set or assigned to the wrong field. These tests feed the factories a
 * proxy config whose every answer is derived from the getter name, which makes any
 * such cross-wiring visible.
 */
public class TickSettingsTest
{
	private static final Map<String, Integer> VALUES = new HashMap<>();
	private static final AtomicInteger NEXT_VALUE = new AtomicInteger(1);

	@Test
	public void oneReadsOnlyItsOwnGetters()
	{
		assertSuffix("One", TickSettings::one);
	}

	@Test
	public void twoReadsOnlyItsOwnGetters()
	{
		assertSuffix("Two", TickSettings::two);
	}

	@Test
	public void threeReadsOnlyItsOwnGetters()
	{
		assertSuffix("Three", TickSettings::three);
	}

	@Test
	public void allThreeFactoriesReadTheSameSettings()
	{
		assertEquals(baseNames("One", TickSettings::one), baseNames("Two", TickSettings::two));
		assertEquals(baseNames("One", TickSettings::one), baseNames("Three", TickSettings::three));
	}

	@Test
	public void oneMapsEveryGetterToItsMatchingField()
	{
		assertFields(TickSettings.one(recordingConfig(new ArrayList<>())), "One");
	}

	@Test
	public void twoMapsEveryGetterToItsMatchingField()
	{
		assertFields(TickSettings.two(recordingConfig(new ArrayList<>())), "Two");
	}

	@Test
	public void threeMapsEveryGetterToItsMatchingField()
	{
		assertFields(TickSettings.three(recordingConfig(new ArrayList<>())), "Three");
	}

	private static void assertFields(TickSettings s, String suffix)
	{
		assertEquals(intFor("numberOfTicks" + suffix), s.numberOfTicks);
		assertEquals(intFor("amountPerRow" + suffix), s.amountPerRow);
		assertEquals(intFor("sizeOfTickShapes" + suffix), s.shapeSize);
		assertEquals(intFor("tickArc" + suffix), s.arc);
		assertEquals(intFor("tickTextSize" + suffix), s.textSize);
		assertEquals(intFor("horizontalSpacing" + suffix), s.horizontalSpacing);
		assertEquals(intFor("verticalSpacing" + suffix), s.verticalSpacing);
		assertEquals(colourFor("tickColour" + suffix), s.tickColour);
		assertEquals(colourFor("currentTickColour" + suffix), s.currentTickColour);
		assertEquals(colourFor("tickTextColour" + suffix), s.textColour);
		assertEquals(colourFor("currentTickTextColour" + suffix), s.currentTextColour);
		assertEquals(shapeFor("tickShape" + suffix), s.shape);
		assertEquals(tabFor("exclusiveTab" + suffix), s.exclusiveTab);
		// booleans answer true only for the text toggle, so a swap flips both
		assertTrue(s.showText);
		assertTrue(!s.showShape);
	}

	private static void assertSuffix(String suffix, Function<VisualTicksConfig, TickSettings> factory)
	{
		List<String> called = new ArrayList<>();
		factory.apply(recordingConfig(called));

		assertEquals("every field should come from one getter", 15, called.size());
		for (String name : called)
		{
			assertTrue(name + " does not belong to tick set " + suffix, name.endsWith(suffix));
		}
	}

	private static List<String> baseNames(String suffix, Function<VisualTicksConfig, TickSettings> factory)
	{
		List<String> called = new ArrayList<>();
		factory.apply(recordingConfig(called));

		List<String> bases = new ArrayList<>();
		for (String name : called)
		{
			bases.add(name.substring(0, name.length() - suffix.length()));
		}
		return bases;
	}

	private static VisualTicksConfig recordingConfig(List<String> called)
	{
		InvocationHandler handler = (proxy, method, args) ->
		{
			String name = method.getName();
			called.add(name);

			Class<?> type = method.getReturnType();
			if (type == int.class)
			{
				return intFor(name);
			}
			if (type == boolean.class)
			{
				return name.startsWith("shouldShowText");
			}
			if (type == Color.class)
			{
				return colourFor(name);
			}
			if (type == TickShape.class)
			{
				return shapeFor(name);
			}
			if (type == InterfaceTab.class)
			{
				return tabFor(name);
			}
			throw new AssertionError("unhandled return type " + type + " for " + name);
		};

		return (VisualTicksConfig) Proxy.newProxyInstance(
			TickSettingsTest.class.getClassLoader(),
			new Class<?>[]{VisualTicksConfig.class},
			handler);
	}

	/**
	 * Distinct per getter name, so a mis-assigned field lands on the wrong number.
	 * Assigned sequentially rather than hashed so two getters can never collide.
	 */
	private static synchronized int intFor(String name)
	{
		return VALUES.computeIfAbsent(name, ignored -> NEXT_VALUE.getAndIncrement());
	}

	/**
	 * Enums have too few constants to be distinct per getter, so they are distinct per
	 * tick set instead: a factory reading another set's shape or tab lands on the wrong one.
	 */
	private static TickShape shapeFor(String name)
	{
		return TickShape.values()[setIndex(name)];
	}

	private static InterfaceTab tabFor(String name)
	{
		return InterfaceTab.values()[setIndex(name) + 1];
	}

	private static int setIndex(String name)
	{
		if (name.endsWith("One"))
		{
			return 0;
		}
		if (name.endsWith("Two"))
		{
			return 1;
		}
		if (name.endsWith("Three"))
		{
			return 2;
		}
		throw new AssertionError(name + " has no tick set suffix");
	}

	private static Color colourFor(String name)
	{
		return new Color(intFor(name));
	}
}
